DECLARE
  v_esp NUMBER;
BEGIN
  SELECT id_especialidad INTO v_esp FROM MEDICO WHERE rut_medico = :NEW.rut_medico;
  IF v_esp IS NULL THEN
    RAISE_APPLICATION_ERROR(-20003, 'MÃ©dico sin especialidad registrada.');
  ELSIF v_esp != :NEW.id_especialidad THEN
    RAISE_APPLICATION_ERROR(-20004, 'La especialidad de la atenciÃ³n no coincide con la especialidad del mÃ©dico.');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20005, 'MÃ©dico no existe.');
END;
